<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
$canCreate=has_permission('ambulance.requests.create');$canManage=has_permission('ambulance.manage');$canView=has_permission('emergency_requests.view');
if(!$canCreate&&!$canManage&&!$canView){http_response_code(403);exit('Ambulance access is not assigned to your account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){
  require_permission('ambulance.requests.create');$patient=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT);$patient=$patient?:null;$pickup=trim((string)($_POST['pickup_location']??''));$destination=trim((string)($_POST['destination']??''));$notes=trim((string)($_POST['transport_notes']??''));
  if(strlen($pickup)<2||strlen($pickup)>255||strlen($destination)<2||strlen($destination)>255||strlen($notes)>500){set_flash('danger','Enter pickup and destination details. Keep each location under 255 characters.');redirect('/hospital%20management/ambulance/index.php');}
  if($patient!==null){$q=$pdo->prepare('SELECT id FROM patients WHERE id=:id');$q->execute(['id'=>$patient]);if(!$q->fetch()){set_flash('danger','Select a valid patient.');redirect('/hospital%20management/ambulance/index.php');}}
  $q=$pdo->prepare("INSERT INTO ambulance_requests(patient_id,requested_by,pickup_location,destination,transport_notes) VALUES(:patient,:user,:pickup,:destination,:notes)");$q->execute(['patient'=>$patient,'user'=>current_user()['id'],'pickup'=>$pickup,'destination'=>$destination,'notes'=>$notes?:null]);$id=(string)$pdo->lastInsertId();record_audit('create','ambulance_request',$id,'Patient transport requested');notify_staff('ambulance_requested','ambulance_request',$id,current_user()['full_name'].' requested ambulance transport.');set_flash('success','Ambulance request submitted.');
 }elseif($action==='claim'){
  require_permission('ambulance.manage');$id=filter_var($_POST['request_id']??'',FILTER_VALIDATE_INT);$q=$pdo->prepare("UPDATE ambulance_requests SET status='assigned',driver_id=:driver WHERE id=:id AND status='requested'");$q->execute(['driver'=>current_user()['id'],'id'=>$id]);if($q->rowCount()){record_audit('assign','ambulance_request',(string)$id,'Driver accepted transport request');notify_staff('ambulance_updated','ambulance_request',(string)$id,current_user()['full_name'].' accepted an ambulance transport request.');set_flash('success','Transport assigned to you.');}else set_flash('warning','Request has already been assigned or is unavailable.');
 }elseif($action==='status'){
  require_permission('ambulance.manage');$id=filter_var($_POST['request_id']??'',FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,['en_route','completed'],true)){http_response_code(400);exit('Invalid transport status.');}$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT status,driver_id FROM ambulance_requests WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$row=$q->fetch();$systemOwner=in_array(current_user()['role_key'],['admin','super_admin'],true);if(!$row||(!$systemOwner&&(int)$row['driver_id']!==(int)current_user()['id'])||($status==='en_route'&&$row['status']!=='assigned')||($status==='completed'&&$row['status']!=='en_route'))throw new RuntimeException('Transport status transition is not allowed.');$pdo->prepare('UPDATE ambulance_requests SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);record_audit('update','ambulance_request',(string)$id,'Transport status changed to '.$status);notify_staff('ambulance_updated','ambulance_request',(string)$id,current_user()['full_name'].' updated transport status to '.str_replace('_',' ',$status).'.');$pdo->commit();set_flash('success','Transport status updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Transport status could not be updated.');}
 }else{http_response_code(400);exit('Unknown transport action.');}redirect('/hospital%20management/ambulance/index.php');
}
$conditions=[];$params=[];if(!$canManage){$conditions[]='ar.requested_by=:user_id';$params['user_id']=current_user()['id'];}$where=$conditions?'WHERE '.implode(' AND ',$conditions):'';$q=$pdo->prepare("SELECT ar.*,p.patient_no,p.first_name,p.last_name,u.full_name AS driver_name FROM ambulance_requests ar LEFT JOIN patients p ON p.id=ar.patient_id LEFT JOIN users u ON u.id=ar.driver_id {$where} ORDER BY CASE WHEN ar.status IN ('requested','assigned','en_route') THEN 0 ELSE 1 END,ar.requested_at DESC LIMIT 200");$q->execute($params);$requests=$q->fetchAll();
$patients=($canCreate&&has_permission('patients.view'))?$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY last_name,first_name LIMIT 1000')->fetchAll():[];
$pageTitle='Ambulance transport';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Ambulance and transport</h2><p>Request emergency transport and follow dispatch status.</p></div></div>
<?php if($canCreate):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>New transport request</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="create"><?php if(has_permission('patients.view')):?><div class="col-md-3"><label class="form-label">Patient (optional)</label><select class="form-select" name="patient_id"><option value="">Unregistered / unknown</option><?php foreach($patients as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['patient_no'].' · '.$p['last_name'].', '.$p['first_name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-3"><label class="form-label">Pickup location</label><input class="form-control" name="pickup_location" maxlength="255" required></div><div class="col-md-3"><label class="form-label">Destination</label><input class="form-control" name="destination" maxlength="255" required></div><div class="col-md-2"><label class="form-label">Transport details</label><input class="form-control" name="transport_notes" maxlength="500" placeholder="Mobility / contact details"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Request</button></div></form></section><?php endif;?>
<section class="content-card"><div class="card-heading"><h3><?= $canManage?'Dispatch queue':'My requests' ?></h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Requested</th><th>Patient</th><th>Pickup</th><th>Destination</th><th>Details</th><th>Driver</th><th>Status / action</th></tr></thead><tbody><?php if(!$requests):?><tr><td class="empty-state" colspan="7">No transport requests.</td></tr><?php else:foreach($requests as $r):?><tr><td><?=e(date('M j, Y g:i a',strtotime($r['requested_at'])))?></td><td><?=e($r['patient_id']?$r['last_name'].', '.$r['first_name'].' ('.$r['patient_no'].')':'Not registered')?></td><td><?=e($r['pickup_location'])?></td><td><?=e($r['destination'])?></td><td><?=e($r['transport_notes']?:'—')?></td><td><?=e($r['driver_name']??'Unassigned')?></td><td><?php if($canManage&&$r['status']==='requested'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="claim"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-primary">Accept</button></form><?php elseif($canManage&&$r['driver_id']&&(int)$r['driver_id']===(int)current_user()['id']&&$r['status']==='assigned'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-primary" name="status" value="en_route">En route</button></form><?php elseif($canManage&&$r['driver_id']&&(int)$r['driver_id']===(int)current_user()['id']&&$r['status']==='en_route'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-primary" name="status" value="completed">Complete trip</button></form><?php else:?><?=e(ucwords(str_replace('_',' ',$r['status'])))?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
